style.css:
/* Dark Cyber Pink */
body { background: #150D16 !important; color: #FFD9F0 !important; }
h1, h2, h3 { color: #FF4DB8 !important; }
p { color: #D8A6C8 !important; }
a { color: #FF69C8 !important; }
button {
  background: #8E145E !important;
  color: white !important;
  border: 1px solid #FF1493 !important;
  border-radius: 5px !important;
}
input, textarea {
  background: #261526 !important;
  color: #FFD9F0 !important;
  border: 1px solid #9C337D !important;
}
::selection { background: #FF1493; color: white; }
